SELECT table_name FROM information_schema.tables WHERE table_schema = 'app' AND (table_name ILIKE '%game%' OR table_name ILIKE '%tournament%' OR table_name ILIKE '%league%' OR table_name ILIKE '%challenge_game%' OR table_name ILIKE '%challenge_session%' OR table_name ILIKE '%challenge_question%' OR table_name ILIKE '%challenge_rank%' OR table_name ILIKE '%challenge_badge%') ORDER BY table_name;
